ul.points {{ list-style: none; padding: 0; margin: 2mm 0 4mm 0; }}
ul.points li {{ position: relative; padding-left: 8mm; margin-bottom: 2mm; color: #e0e0e0; }}
ul.points li::before {{ content: '•'; position: absolute; left: 0;
  color: {G}; font-weight: 700; }}
.kill {{ background: #0c0c0c; border-left: 3pt solid {G};
  padding: 3mm 4mm; margin: 3mm 0; }}
.kill p {{ color: #fff; font-size: 11pt; }}
.cover {{ page: cover; width: 210mm; height: 297mm; background: {BG};
  display: flex; flex-direction: column; justify-content: center;
  padding: 0 24mm; page-break-after: always; position: relative; }}
.cover .tag {{ font-size: 7.5pt; letter-spacing: 0.25em; text-transform: uppercase;
  color: {G}; margin-bottom: 6mm; font-weight: 600; }}
.cover .title {{ font-size: 28pt; font-weight: 800; color: #fff; line-height: 1.1;
  margin-bottom: 3mm; }}
.cover .part {{ font-size: 18pt; font-weight: 700; color: {G}; margin: 8mm 0; }}
.cover .sub {{ font-size: 13pt; color: #ababab; line-height: 1.6; }}
.cover .note {{ font-size: 9pt; color: #666; margin-top: 10mm; line-height: 1.4; }}
.cover .brand {{ position: absolute; bottom: 14mm; left: 24mm;
  font-size: 7.5pt; letter-spacing: 0.3em; text-transform: uppercase;
  color: #222; border-bottom: 1pt solid #222; padding-bottom: 1mm; }}
.cover .accent {{ position: absolute; bottom: 8mm; left: 24mm;
  font-size: 6.5pt; letter-spacing: 0.3em; text-transform: uppercase;
  color: {G}; }}
.layer {{ background: #0a0a0a; border-left: 2pt solid {G}; padding: 3mm 4mm; margin: 3mm 0; }}
.layer-name {{ font-size: 11pt; font-weight: 700; color: {G}; margin-bottom: 1mm; letter-spacing: 0.05em; text-transform: uppercase; }}
.layer-desc {{ font-size: 10pt; color: #d0d0d0; }}
"""

def page(inner, pn=True):
    num = f'<div class="page-num">{pn}</div>' if pn else ""
    return f'<div class="page">{inner}{num}</div>'

def sec(num, title):
    return f'<div class="sec-head"><span class="num">{num}</span>{title}</div>'

def spacer(mm):
    return f'<div style="height:{mm}mm"></div>'

def kill(t):
    return f'<div class="kill"><p>{t}</p></div>'

def note(t):
    return f'<p class="note">{t}</p>'

def ul(items):
    lis = "".join(f"<li>{i}</li>" for i in items)
    return f'<ul class="points">{lis}</ul>'

def layer(num, name, desc):
    return f'<div class="layer"><div class="layer-name">Layer {num} - {name}</div><div class="layer-desc">{desc}</div></div>'

